// ─────────────────────────────────────────────────────────────────────────────
// WORD GAPS WORKSHEET — a self-contained dashboard plugin.
//
// The dashboard loads this plugin by calling `WordGapsWorksheet(dashboard)`
// with its configurations + layouts (see plugins/index.ts). Within this
// function the plugin describes:
//   - its SIDEBAR LABEL ("Word Gaps", glyph "§") and which grades offer it;
//   - what happens when its label is CLICKED: its worksheet — generated by
//     the generator below — shows in the content area via the framework's
//     standard worksheet recipe (dashboard.createWorksheet).
//
// Fully self-contained: deleting this file and its line in plugins/index.ts
// removes the Word Gaps worksheet without affecting the framework or any
// other plugin.
// ─────────────────────────────────────────────────────────────────────────────

import type { Caps, DashboardFramework, DashboardPlugin, GradeConfig, RawProblem, Rng, WorksheetSpec } from '../framework';
import { shuffleWords } from './words';

// Word-gap items: [sentence with one "__", the correct word, two printed
// non-fitting options]. Tier 2 = basic; tier 3 adds longer vocabulary.
const WORDGAP_TIER2: [string, string, [string, string]][] = [
    ['I drink a glass of __ .', 'milk', ['cat', 'tree']],
    ["We read a __ in class.", 'book', ['door', 'fish']],
    ['My __ is very small.', 'cat', ['desk', 'milk']],
    ['The sun is in the __ .', 'sky', ['water', 'box']],
    ["The fish lives in the __ .", 'water', ['sky', 'box']],
    ['I wear my __ to school.', 'hat', ['book', 'milk']]
];
const WORDGAP_TIER3_EXTRA: [string, string, [string, string]][] = [
    ['We eat __ for breakfast.', 'bread', ['shoes', 'sky']],
    ["She brushes her __ every morning.", 'teeth', ['boots', 'sky']],
    ['I put my __ on before we go.', 'boots', ['bread', 'bird']],
    ['The chicken lays __ in the morning.', 'eggs', ['birds', 'boots']]
];

// Word gaps: a sentence with one gap printed as a fill-in line beside three
// choices, one of which fits.
function generateWordGap(rng: Rng, caps: Caps, count: number): RawProblem[] {
    const out: RawProblem[] = [];
    const pool = caps.wordTier >= 3 ? [...WORDGAP_TIER2, ...WORDGAP_TIER3_EXTRA] : WORDGAP_TIER2;
    for (let i = 0; i < count; i++) {
        const [sentence, answer, [bad1, bad2]] = rng.pick(pool);
        const options = shuffleWords(rng, [answer, bad1, bad2]);
        out.push({ prompt: `Choose the best word: ${sentence} (${options.join(', ')})`, answer });
    }
    return out;
}

// The plugin's declarative spec (exported for its own tests). Gap sentences
// are prose — single-column via singleColumn.
export const wordgapSpec: WorksheetSpec = {
    id: 'wordgap',
    label: 'Word Gaps',
    icon: '§',
    perPage: 16,
    singleColumn: true,
    offered: (grade: GradeConfig) => grade.available.includes('wordgap'),
    scope: () => 'best word in the gap',
    generate: generateWordGap
};

// The plugin: a function the dashboard calls with its framework bundle.
export function WordGapsWorksheet(dashboard: DashboardFramework): DashboardPlugin {
    return dashboard.createWorksheet(wordgapSpec);
}
